# ============================================================
# PIN EXTRACTOR FROM POEMS
# ============================================================
#
# Description:
# This script defines a function that extracts hidden PIN codes
# from poems. Each poem consists of multiple lines, and each
# line contributes exactly one digit to the final PIN.
#
# The PIN is generated by the following logic:
# - Each poem is split into individual lines.
# - For each line, the line index (starting from 0) is used.
# - The word at the position matching the line index is selected.
# - The length of that word becomes the digit for that line.
# - If a line does not contain enough words to match the index,
#   the digit "0" is used instead.
#
# The result is a list of PIN codes, one for each poem provided.
#
# ============================================================
# Function Definition
# ============================================================

# create a pin extractor, the pin digits are hidden in each line of a poem.

def pin_extractor(poems):
    # This list will store the extracted PIN codes
    secret_codes = []

    # Iterate over each poem in the input list
    for poem in poems:
        # Initialize an empty string to build the PIN for the poem
        secret_code = ''

        # Split the poem into individual lines
        lines = poem.split('\n')

        # Enumerate through each line along with its index
        for line_index, line in enumerate(lines):
            # Split the line into words
            words = line.split()

            # If the line contains a word at the current index
            if len(words) > line_index:
                # Append the length of that word to the PIN
                secret_code += str(len(words[line_index]))
            else:
                # If no word exists at that index, append '0'
                secret_code += '0'

        # Add the completed PIN for this poem to the list
        secret_codes.append(secret_code)

    # Return the list of extracted PIN codes
    return secret_codes


# ============================================================
# Sample Poems Used for PIN Extraction
# ============================================================

poem = """Stars and the moon
shine in the sky
white and
until the end of the night"""

poem2 = (
    'The grass is green\n'
    'here and there\n'
    'hoping for rain\n'
    'before it turns yellow'
)

poem3 = (
    'There\n'
    'once\n'
    'was\n'
    'a\n'
    'dragon'
)

# ============================================================
# Function Execution and Output
# ============================================================

# Extract and print PIN codes from the provided poems
print(pin_extractor([poem, poem2, poem3]))

# ============================================================
# Expected Behavior Notes
# ============================================================
#
# - Each poem produces a numeric string (PIN).
# - The number of digits in the PIN equals the number of lines
#   in the poem.
# - Short or single-word lines may contribute a "0" if the
#   required indexed word does not exist.
#
# This approach demonstrates string manipulation, list handling,
# loops, and conditional logic in Python.
#
# ============================================================
